package com.example.courslens.service; import org.apache.poi.xslf.usermodel.*; import org.springframework.stereotype.Component; import java.nio.file.*; import java.util.*;
@Component class PptxDocumentExtractor implements DocumentExtractor {public boolean supports(String t){return t.equals("PPTX");}public List<ExtractedPage> extract(Path f,String m)throws Exception{try(XMLSlideShow show=new XMLSlideShow(Files.newInputStream(f))){List<ExtractedPage> out=new ArrayList<>();int n=1;for(XSLFSlide slide:show.getSlides()){StringBuilder b=new StringBuilder();for(XSLFShape shape:slide.getShapes())if(shape instanceof XSLFTextShape text)b.append(text.getText()).append('\n');out.add(new ExtractedPage(n++,b.toString().trim(),false,"SLIDE"));}return out;}}}
